def select_references(
    chapter: Chapter,
    portraits: dict[str, Path],
) -> list[Path]:
    missing = set(chapter.characters) - portraits.keys()
    if missing:
        raise ValueError(f"Missing character portraits: {sorted(missing)}")
    return [portraits[name] for name in dict.fromkeys(chapter.characters)]
